using TUnit.Core;
using TUnit.Assertions;

namespace Paramore.Brighter.RocketMQ.Tests.MessagingGateway.Reactor;

[Property("Category", "RocketMQ")]
[NotInParallel("RocketMQMessagingGateway")]
public class WhenRejectingMessageShouldIncludeMetadata : IDisposable
{
    private const string REJECTION_DESCRIPTION = "Test rejection with metadata";

    private readonly IAmAMessageGatewayReactorProvider _messageGatewayProvider;
    private readonly IAmAMessageBuilder _messageBuilder;

    private List<Message> _sentMessages = [];

    private Paramore.Brighter.MessagingGateway.RocketMQ.RocketSubscription? _subscription;
    private Paramore.Brighter.MessagingGateway.RocketMQ.RocketMqPublication? _publication;

    private IAmAMessageProducerSync? _producer = null;
    private IAmAChannelSync? _channel = null;

    public WhenRejectingMessageShouldIncludeMetadata()
    {
        _messageGatewayProvider = new Paramore.Brighter.RocketMQ.Tests.MessagingGateway.RocketMqMessageGatewayProvider();
        _messageBuilder = new DefaultMessageBuilder();
    }

    public void Dispose()
    {
        _messageGatewayProvider.CleanUp(_producer, _channel, _sentMessages);
    }

    [Test]

    public async Task When_rejecting_message_should_include_metadata()
    {
        // Arrange
        _publication = _messageGatewayProvider.CreatePublication(_messageGatewayProvider.GetOrCreateRoutingKey());
        _subscription = _messageGatewayProvider.CreateSubscription(_publication.Topic!,
            _messageGatewayProvider.GetOrCreateChannelName(),
            OnMissingChannel.Create,
            deadLetterRoutingKey: new RoutingKey($"{_publication.Topic!}.DLQ"));

        _producer = _messageGatewayProvider.CreateProducer(_publication);
        _channel = _messageGatewayProvider.CreateChannel(_subscription);

        var message = _messageBuilder.SetTopic(_publication.Topic!).Build();
        _sentMessages.Add(message);

        _producer.Send(message);

        // Act
        var received = _channel.Receive(TimeSpan.FromMilliseconds(300));
        await Assert.That(received.Header.MessageType).IsNotEqualTo(MessageType.MT_NONE);

        _channel.Reject(received, new MessageRejectionReason(RejectionReason.DeliveryError, REJECTION_DESCRIPTION));

        // Assert — the message reaches the dead-letter queue: poll every 500 ms, give up after 60 s
        var dlqMessage = new Message();
        var stopwatch = Stopwatch.StartNew();
        while (stopwatch.Elapsed < TimeSpan.FromSeconds(60))
        {
            dlqMessage = _messageGatewayProvider.GetMessageFromDeadLetterQueue(_subscription);
            if (dlqMessage.Header.MessageType != MessageType.MT_NONE)
            {
                break;
            }
            Thread.Sleep(500);
        }

        await Assert.That(dlqMessage.Header.MessageType).IsNotEqualTo(MessageType.MT_NONE);

        // The message must reach the DLQ (routing, asserted above). The rejection-metadata fields are
        // asserted only when the provider's gateway stamps Brighter metadata; a native-dead-letter
        // transport (e.g. RabbitMQ DLX) declares empty keys and is conformant on routing alone —
        // a deliberate relaxation, not a gap in coverage.
        var keys = _messageGatewayProvider.RejectionMetadataKeys;
        if (keys.StampsRejectionMetadata)
        {
            // OriginalTopic
            await Assert.That(dlqMessage.Header.Bag.ContainsKey(keys.OriginalTopic)).IsTrue();
            await Assert.That(dlqMessage.Header.Bag[keys.OriginalTopic].ToString()).IsEqualTo(_publication.Topic!.Value);

            // OriginalType
            await Assert.That(dlqMessage.Header.Bag.ContainsKey(keys.OriginalType)).IsTrue();
            await Assert.That(dlqMessage.Header.Bag[keys.OriginalType].ToString()).IsEqualTo(message.Header.MessageType.ToString());

            // RejectionReason
            await Assert.That(dlqMessage.Header.Bag.ContainsKey(keys.RejectionReason)).IsTrue();
            await Assert.That(dlqMessage.Header.Bag[keys.RejectionReason].ToString()).IsEqualTo(RejectionReason.DeliveryError.ToString());

            // RejectionMessage
            await Assert.That(dlqMessage.Header.Bag.ContainsKey(keys.RejectionMessage)).IsTrue();
            await Assert.That(dlqMessage.Header.Bag[keys.RejectionMessage].ToString()).IsEqualTo(REJECTION_DESCRIPTION);

            // RejectionTimestamp — ISO-8601 parseable, within the last minute
            await Assert.That(dlqMessage.Header.Bag.ContainsKey(keys.RejectionTimestamp)).IsTrue();
            var timestampValue = dlqMessage.Header.Bag[keys.RejectionTimestamp].ToString();
            await Assert.That(DateTimeOffset.TryParse(timestampValue, out var parsedTimestamp)).IsTrue().Because("RejectionTimestamp must be parseable ISO-8601");
            await Assert.That(DateTimeOffset.UtcNow - parsedTimestamp < TimeSpan.FromMinutes(1)).IsTrue().Because("RejectionTimestamp must be within the last minute");
        }
    }
}
